CREATE VIEW vw_schedule_details AS SELECT s.*,cs.code section_code,c.name course_name,la.lecturer_id,u.full_name lecturer_name,r.code room_code,ss.sort_order start_order,es.sort_order end_order FROM schedules s JOIN course_sections cs ON cs.id=s.course_section_id JOIN courses c ON c.id=cs.course_id JOIN lecturer_assignments la ON la.id=s.lecturer_assignment_id JOIN users u ON u.id=la.lecturer_id JOIN classrooms r ON r.id=s.classroom_id JOIN time_slots ss ON ss.id=s.start_slot_id JOIN time_slots es ON es.id=s.end_slot_id;
CREATE VIEW vw_student_timetable AS SELECT e.student_id,s.* FROM student_enrollments e JOIN vw_schedule_details s ON s.course_section_id=e.course_section_id WHERE e.status='ACTIVE' AND s.status='PUBLISHED';
CREATE VIEW vw_lecturer_timetable AS SELECT * FROM vw_schedule_details WHERE status='PUBLISHED';
CREATE VIEW vw_room_utilization AS SELECT classroom_id,cs.semester_id,SUM(es.sort_order-ss.sort_order+1) weekly_slots FROM schedules s JOIN course_sections cs ON cs.id=s.course_section_id JOIN time_slots ss ON ss.id=s.start_slot_id JOIN time_slots es ON es.id=s.end_slot_id WHERE s.status='PUBLISHED' GROUP BY classroom_id,cs.semester_id;
